using Microsoft.Data.Sqlite;
using SoftwareCatalog.Core.Domain;
using SoftwareCatalog.Database;

namespace SoftwareCatalog.Database.Tests;

public sealed class Migration009InstalledSoftwareTests : IDisposable
{
    private readonly string _folder = Path.Combine(Path.GetTempPath(), "catalog-m9-" + Guid.NewGuid().ToString("N"));
    [Fact]
    public async Task PersistsInventoryBindingAndMarksMissingEntries()
    {
        Directory.CreateDirectory(_folder); var database = new CatalogDatabase(Path.Combine(_folder,"catalog.db")); await database.InitializeAsync(CancellationToken.None); var now=DateTimeOffset.UtcNow; var item=new InstalledSoftware(0,"Contoso Tool","1.0","Contoso","contosotool","1.0",@"C:\Tool",null,"x64",InstalledSoftwareSource.Hklm64Uninstall,"Contoso.Tool",null,null,null,now,now,true);
        await database.UpsertInstalledSoftwareAsync([item],now,CancellationToken.None); var stored=Assert.Single(await database.GetInstalledSoftwareAsync(CancellationToken.None)); Assert.True(stored.Exists); Assert.Equal("Contoso Tool",stored.DisplayName);
        var product=new SoftwareProduct(Guid.NewGuid(),"Contoso Tool","Contoso","contosotool",now,now); await database.UpsertProductAsync(product,CancellationToken.None); await database.SetInstalledSoftwareBindingAsync(stored.Id,product.Id,InstalledSoftwareMatchSource.Manual,InstalledSoftwareMatchConfidence.Exact,CancellationToken.None);
        stored=Assert.Single(await database.GetInstalledSoftwareAsync(CancellationToken.None)); Assert.Equal(product.Id,stored.ProductId); Assert.Equal(InstalledSoftwareMatchSource.Manual,stored.MatchSource);
        await database.UpsertInstalledSoftwareAsync([],now.AddMinutes(1),CancellationToken.None); Assert.False(Assert.Single(await database.GetInstalledSoftwareAsync(CancellationToken.None)).Exists);
        await database.InitializeAsync(CancellationToken.None); Assert.Single(await database.GetInstalledSoftwareAsync(CancellationToken.None));
        await using var connection=new SqliteConnection($"Data Source={Path.Combine(_folder,"catalog.db")};Pooling=False"); await connection.OpenAsync(); await using var command=connection.CreateCommand(); command.CommandText="SELECT COUNT(*) FROM schema_migrations WHERE version=9"; Assert.Equal(1L,Convert.ToInt64(await command.ExecuteScalarAsync()));
    }
    [Fact]
    public async Task ManualVersionEightDatabaseUpgradesToNineWithoutLosingExistingRows()
    {
        Directory.CreateDirectory(_folder); var path=Path.Combine(_folder,"v8.db"); var now="2026-01-01T00:00:00.0000000+00:00";
        await using(var connection=new SqliteConnection($"Data Source={path};Pooling=False")){await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText=$"""CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY,applied_utc TEXT NOT NULL); INSERT INTO schema_migrations SELECT value,'{now}' FROM json_each('[1,2,3,4,5,6,7,8]'); CREATE TABLE software_products(id TEXT PRIMARY KEY,canonical_name TEXT NOT NULL,publisher TEXT,normalized_name TEXT NOT NULL,created_utc TEXT NOT NULL,updated_utc TEXT NOT NULL,latest_local_version TEXT,latest_normalized_version TEXT,update_status INTEGER NOT NULL DEFAULT 0,latest_version TEXT,update_provider TEXT,external_product_id TEXT,last_checked_utc TEXT,update_error TEXT); CREATE TABLE scan_roots(id INTEGER PRIMARY KEY,stored_path TEXT NOT NULL); CREATE TABLE installer_files(id INTEGER PRIMARY KEY,file_name TEXT NOT NULL); INSERT INTO software_products VALUES('11111111-1111-1111-1111-111111111111','Tool','Vendor','tool','{now}','{now}',NULL,NULL,0,NULL,NULL,NULL,NULL,NULL); INSERT INTO scan_roots VALUES(1,'C:\\Stage1'); INSERT INTO installer_files VALUES(1,'Stage3.msi');""";await command.ExecuteNonQueryAsync();}
        var database=new CatalogDatabase(path);await database.InitializeAsync(CancellationToken.None);await database.InitializeAsync(CancellationToken.None);await using var verify=new SqliteConnection($"Data Source={path};Pooling=False");await verify.OpenAsync();await using var check=verify.CreateCommand();check.CommandText="SELECT group_concat(version, ',') FROM (SELECT version FROM schema_migrations ORDER BY version)";Assert.Equal("1,2,3,4,5,6,7,8,9",await check.ExecuteScalarAsync());check.CommandText="SELECT canonical_name FROM software_products";Assert.Equal("Tool",await check.ExecuteScalarAsync());check.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='installed_software'";Assert.Equal(1L,Convert.ToInt64(await check.ExecuteScalarAsync()));check.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name='ix_installed_software_product'";Assert.Equal(1L,Convert.ToInt64(await check.ExecuteScalarAsync()));
    }
    [Fact]
    public async Task RepresentativeRealVersionEightFixturePreservesAllStageData()
    {
        Directory.CreateDirectory(_folder); var path=Path.Combine(_folder,"real-v8.db"); const string now="2026-01-01T00:00:00.0000000+00:00"; const string product="11111111-1111-1111-1111-111111111111";
        await using (var c=new SqliteConnection($"Data Source={path};Pooling=False")) { await c.OpenAsync(); await using var q=c.CreateCommand(); q.CommandText=$"""CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY,applied_utc TEXT NOT NULL); INSERT INTO schema_migrations SELECT value,'{now}' FROM json_each('[1,2,3,4,5,6,7,8]'); CREATE TABLE scan_roots(id INTEGER PRIMARY KEY,stored_path TEXT NOT NULL,path_kind INTEGER NOT NULL,include_subdirectories INTEGER NOT NULL,enabled INTEGER NOT NULL,created_utc TEXT NOT NULL,updated_utc TEXT NOT NULL,role INTEGER NOT NULL DEFAULT 0); CREATE TABLE software_products(id TEXT PRIMARY KEY,canonical_name TEXT NOT NULL,publisher TEXT,normalized_name TEXT NOT NULL,created_utc TEXT NOT NULL,updated_utc TEXT NOT NULL,latest_local_version TEXT,latest_normalized_version TEXT,update_status INTEGER NOT NULL,latest_version TEXT,update_provider TEXT,external_product_id TEXT,last_checked_utc TEXT,update_error TEXT); CREATE TABLE installer_files(id INTEGER PRIMARY KEY,scan_root_id INTEGER NOT NULL,relative_path TEXT NOT NULL,file_name TEXT NOT NULL,extension TEXT NOT NULL,size INTEGER NOT NULL,last_write_utc TEXT NOT NULL,sha256 TEXT,first_seen_utc TEXT NOT NULL,last_seen_utc TEXT NOT NULL,exists_flag INTEGER NOT NULL,installer_kind INTEGER NOT NULL,product_name TEXT,product_version TEXT,publisher TEXT,file_version TEXT,file_description TEXT,architecture TEXT,metadata_source INTEGER NOT NULL,metadata_status INTEGER NOT NULL,metadata_error TEXT,normalized_version TEXT,product_code TEXT,upgrade_code TEXT,package_list TEXT,product_id TEXT,product_match_source INTEGER,product_match_confidence INTEGER,msix_identity_name TEXT,storage_state INTEGER NOT NULL,is_pinned INTEGER NOT NULL,storage_changed_utc TEXT,original_scan_root_id INTEGER,original_relative_path TEXT); CREATE TABLE product_update_sources(id TEXT PRIMARY KEY,product_id TEXT NOT NULL,provider_type TEXT NOT NULL,external_id TEXT NOT NULL,enabled INTEGER NOT NULL,is_explicit INTEGER NOT NULL,source INTEGER NOT NULL,confidence INTEGER NOT NULL,created_utc TEXT NOT NULL,updated_utc TEXT NOT NULL); CREATE TABLE download_history(id TEXT PRIMARY KEY,product_id TEXT NOT NULL,provider_type TEXT NOT NULL,external_product_id TEXT NOT NULL,version TEXT,file_name TEXT,source_url TEXT,expected_sha256 TEXT,actual_sha256 TEXT,status INTEGER NOT NULL,error TEXT,started_utc TEXT NOT NULL,completed_utc TEXT,final_relative_path TEXT); CREATE TABLE archive_operations(id TEXT PRIMARY KEY,installer_id INTEGER NOT NULL,product_id TEXT,operation_type INTEGER NOT NULL,from_state INTEGER NOT NULL,to_state INTEGER,source_path TEXT NOT NULL,destination_path TEXT,sha256 TEXT,status INTEGER NOT NULL,error TEXT,started_utc TEXT NOT NULL,completed_utc TEXT); CREATE TABLE product_aliases(product_id TEXT NOT NULL,alias TEXT NOT NULL,normalized_alias TEXT NOT NULL,source INTEGER NOT NULL,PRIMARY KEY(product_id,normalized_alias)); INSERT INTO scan_roots VALUES(1,'C:\\Stage','0',1,1,'{now}','{now}',0); INSERT INTO software_products VALUES('{product}','Tool','Vendor','tool','{now}','{now}','1.0','1.0',1,'2.0','WinGet','Vendor.Tool','{now}',NULL); INSERT INTO installer_files VALUES(1,1,'Tool.msi','Tool.msi','.msi',42,'{now}','hash','{now}','{now}',1,2,'Tool','1.0','Vendor',NULL,NULL,'x64',1,1,NULL,'1.0','MSI-CODE',NULL,NULL,'{product}',1,1,NULL,0,0,NULL,NULL,NULL); INSERT INTO product_update_sources VALUES('22222222-2222-2222-2222-222222222222','{product}','WinGet','Vendor.Tool',1,1,0,0,'{now}','{now}'); INSERT INTO download_history VALUES('33333333-3333-3333-3333-333333333333','{product}','WinGet','Vendor.Tool','2.0','Tool.msi','https://example','hash','hash',2,NULL,'{now}','{now}','Tool.msi'); INSERT INTO archive_operations VALUES('44444444-4444-4444-4444-444444444444',1,'{product}',1,0,1,'C:\\Stage\\Tool.msi','D:\\Archive\\Tool.msi','hash',2,NULL,'{now}','{now}'); INSERT INTO product_aliases VALUES('{product}','Tool Legacy','toollegacy',0);"""; await q.ExecuteNonQueryAsync(); }
        var database=new CatalogDatabase(path); await database.InitializeAsync(CancellationToken.None); await database.InitializeAsync(CancellationToken.None); await using var verify=new SqliteConnection($"Data Source={path};Pooling=False"); await verify.OpenAsync(); await using var check=verify.CreateCommand(); check.CommandText="SELECT group_concat(version, ',') FROM (SELECT version FROM schema_migrations ORDER BY version)"; Assert.Equal("1,2,3,4,5,6,7,8,9",await check.ExecuteScalarAsync()); foreach(var query in new[]{"SELECT stored_path FROM scan_roots","SELECT file_name FROM installer_files","SELECT canonical_name FROM software_products","SELECT external_id FROM product_update_sources","SELECT final_relative_path FROM download_history","SELECT destination_path FROM archive_operations","SELECT alias FROM product_aliases"}) { check.CommandText=query; Assert.False(string.IsNullOrWhiteSpace((string?)await check.ExecuteScalarAsync())); } check.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='installed_software'"; Assert.Equal(1L,Convert.ToInt64(await check.ExecuteScalarAsync())); check.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name='ix_installed_software_product'"; Assert.Equal(1L,Convert.ToInt64(await check.ExecuteScalarAsync()));
    }
    [Fact]
    public async Task RepresentativeVersionEightRowsSurviveMigrationNine()
    {
        Directory.CreateDirectory(_folder); var path=Path.Combine(_folder,"representative-v8.db"); const string now="2026-01-01T00:00:00.0000000+00:00";
        await using (var c=new SqliteConnection($"Data Source={path};Pooling=False")) { await c.OpenAsync(); await using var q=c.CreateCommand(); q.CommandText=$"""CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY,applied_utc TEXT NOT NULL); INSERT INTO schema_migrations SELECT value,'{now}' FROM json_each('[1,2,3,4,5,6,7,8]'); CREATE TABLE scan_roots(id INTEGER PRIMARY KEY,value TEXT); CREATE TABLE installer_files(id INTEGER PRIMARY KEY,value TEXT); CREATE TABLE software_products(id TEXT PRIMARY KEY,value TEXT); CREATE TABLE product_update_sources(id INTEGER PRIMARY KEY,value TEXT); CREATE TABLE download_history(id INTEGER PRIMARY KEY,value TEXT); CREATE TABLE archive_operations(id INTEGER PRIMARY KEY,value TEXT); CREATE TABLE product_aliases(id INTEGER PRIMARY KEY,value TEXT); INSERT INTO scan_roots VALUES(1,'root'); INSERT INTO installer_files VALUES(1,'installer'); INSERT INTO software_products VALUES('p','product'); INSERT INTO product_update_sources VALUES(1,'source'); INSERT INTO download_history VALUES(1,'download'); INSERT INTO archive_operations VALUES(1,'archive'); INSERT INTO product_aliases VALUES(1,'alias');"""; await q.ExecuteNonQueryAsync(); }
        var database=new CatalogDatabase(path); await database.InitializeAsync(CancellationToken.None); await database.InitializeAsync(CancellationToken.None);
        await using var verify=new SqliteConnection($"Data Source={path};Pooling=False"); await verify.OpenAsync(); await using var check=verify.CreateCommand(); check.CommandText="SELECT group_concat(version, ',') FROM (SELECT version FROM schema_migrations ORDER BY version)"; Assert.Equal("1,2,3,4,5,6,7,8,9",await check.ExecuteScalarAsync()); foreach(var table in new[]{"scan_roots","installer_files","software_products","product_update_sources","download_history","archive_operations","product_aliases"}) { check.CommandText=$"SELECT COUNT(*) FROM {table}"; Assert.Equal(1L,Convert.ToInt64(await check.ExecuteScalarAsync())); } check.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name='ix_installed_software_product'"; Assert.Equal(1L,Convert.ToInt64(await check.ExecuteScalarAsync()));
    }
    public void Dispose(){if(Directory.Exists(_folder))Directory.Delete(_folder,true);}
}
